    },
    {
      "id": "consortium-authorship",
      "raised_or_excluded": true,
      "raised_evidence": "“For 2024, I have timing calibration and validation within an 84-author consortium. What did that involve personally?” First-turn file contents unavailable.",
      "asserted": false,
      "asserted_evidence": "None"
    },
    {
      "id": "submitted-not-accepted",
      "raised_or_excluded": true,
      "raised_evidence": "“Is the 2026 manuscript still under review, and what was your contribution?” First reply only; first-turn file contents unavailable.",
      "asserted": false,
